import {DEFAULT_RULES,SEATS,SPEAKER_CRITERIA,timerDisplay,scoreScorecard} from './debate-domain.js';
import {DebateMedia} from './debate-media.js';

const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => JSON.parse(JSON.stringify(value));
const id = () => crypto.randomUUID();
const state = {session:null,client:null,event:null,matchId:null,panel:'overview',busy:false,sync:null,observerPage:0,tiles:new Map(),lastStage:null,judgeDirty:false,pending:null};
const localRehearsal = ['127.0.0.1','localhost'].includes(location.hostname) && globalThis.DEBATE_LOCAL_REHEARSAL === true;
const config = globalThis.DueDiligencePhase2Config || globalThis.DUE_DILIGENCE_PHASE2_CONFIG || {};
let apiBase = localRehearsal ? location.origin : (config.workerUrl || config.apiBaseUrl || '');
let deviceId = id();
const serverNow = () => state.sync ? state.sync.server + performance.now()-state.sync.local : 0;
const currentMatch = () => state.event?.matches.find(m=>m.id === state.matchId) || state.event?.matches.find(m=>m.id === state.event.activeMatchId) || state.event?.matches[0];
const me = () => state.event?.members.find(p=>p.id === state.event.myId);
const host = () => state.event?.ownerId === state.event?.myId || me()?.roles.some(r=>['host','cohost','organizer','co_host'].includes(r));
const official = () => { const m=currentMatch(); return m && [m.moderatorId,m.timekeeperId,m.chiefId,...m.hostIds].includes(state.event.myId); };
const personName = personId => state.event?.members.find(p=>p.id === personId)?.displayName || 'Unassigned';
const sideName = side => side === 'affirmative' ? 'Affirmative' : 'Negative';
const matchPayload = extra => ({matchId:currentMatch()?.id,...extra});
const option = (value,label,selected) => `<option value="${esc(value)}"${selected === value ? ' selected' : ''}>${esc(label)}</option>`;
const peopleOptions = (selected,empty=true) => `${empty?option('','Choose a participant',selected):''}${state.event.members.filter(p=>!p.removed).map(p=>option(p.id,p.displayName,selected)).join('')}`;
const button = (label,action,extra='',className='') => `<button type="button" data-action="${action}" ${extra} class="${className}">${esc(label)}</button>`;
const field = (label,name,value='',type='text',extra='') => `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const selectPerson = (label,name,value='') => `<label>${esc(label)}<select name="${name}">${peopleOptions(value)}</select></label>`;
const formatTime = value => value ? new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short',timeZone:state.event?.timezone || 'Asia/Manila'}).format(new Date(value)) : 'Unscheduled';

function status(message,error=false) { $('status').textContent=message; $('status').dataset.error=String(error); }
async function request(path,body) {
  if (!apiBase) throw new Error('The Debate Room connection is not configured. Your other Due Diligence features remain available.');
  const began=performance.now(); const controller=new AbortController(); const timeout=setTimeout(()=>controller.abort(),18000);
  try {
    const response=await fetch(`${apiBase.replace(/\/$/,'')}${path}`,{method:body?'POST':'GET',cache:'no-store',credentials:'omit',
      headers:{Authorization:`Bearer ${state.session?.access_token || ''}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal});
    const result=await response.json().catch(()=>null);
    if (!response.ok || result?.ok === false) { const error=new Error(result?.error?.message || 'The action could not be confirmed. Refresh to check your saved work.'); error.code=result?.error?.code; error.details=result?.error?.details; error.status=response.status; throw error; }
    if (Number.isFinite(result.serverNow)) state.sync={server:result.serverNow+(performance.now()-began)/2,local:performance.now(),rtt:performance.now()-began};
    return result;
  } finally { clearTimeout(timeout); }
}
function adopt(event,force=false) {
  if (!event || state.event?.id === event.id && event.revision < state.event.revision) return;
  state.event=event; state.matchId=currentMatch()?.id || null;
  $('event').hidden=false; $('lobby').hidden=true; $('event-title').textContent=event.title;
  $('event-meta').textContent=`${event.language} · ${event.timezone} · ${event.status}`;
  $('rehearsal-banner').hidden=!event.rehearsal;
  const fragment=new URLSearchParams({event:event.id}); if(state.matchId)fragment.set('match',state.matchId);
  history.replaceState(null,'',`${location.pathname}#${fragment}`);
  renderLive();
  if (force || !document.activeElement?.closest('form') && !state.judgeDirty) renderPanel();
}
async function refresh() {
  if (!state.event || state.busy) return;
  try { const result=await request(`/debate-room/snapshot?eventId=${encodeURIComponent(state.event.id)}`); adopt(result.event); }
  catch(error) { status(error.message,true); if(error.status===401)await signOutCleanup(); }
}
async function command(name,payload={},eventId=state.event?.id) {
  if (state.busy) throw new Error('The previous action is still being confirmed.');
  const envelope={eventId,command:name,payload,expectedRevision:state.event?.id===eventId?state.event.revision:0,idempotencyKey:id()};
  state.busy=true; state.pending=envelope; status('Saving…');
  try {
    const result=await request('/debate-room/command',envelope); state.pending=null;
    if(result.event)adopt(result.event,true); status('Saved.'); return result.receipt?.result || {};
  } catch(error) {
    if(error.status)state.pending=null;
    status(`${error.message}${!error.status?' The response is unconfirmed; use Retry last action to safely recover its receipt.':''}`,true);
    throw error;
  } finally { state.busy=false; }
}
async function retryPending() {
  if(!state.pending)return refresh();
  const result=await request('/debate-room/command',state.pending); state.pending=null; if(result.event)adopt(result.event,true); status('The saved action is confirmed.');
}
async function loadEvents() {
  const result=await request('/debate-room/events');
  $('events').innerHTML=result.events.length?result.events.map(e=>`<article><h3>${esc(e.title)}</h3><p class="muted">${esc(e.status)}${e.rehearsal?' · Rehearsal':''}</p>${button('Open event','open-event',`data-event="${esc(e.id)}"`)}</article>`).join(''):'<p>You have no events yet. Create a match or join with an invitation.</p>';
}
async function openEvent(eventId) {
  await media.leave(); state.judgeDirty=false;
  const result=await request(`/debate-room/snapshot?eventId=${encodeURIComponent(eventId)}`); state.event=null; adopt(result.event,true);
}
function openDialog(title,fields,onSubmit,submitLabel='Save') {
  $('dialog-title').textContent=title; $('dialog-fields').innerHTML=fields; $('dialog-status').textContent=''; $('dialog-submit').textContent=submitLabel;
  $('dialog-form').onsubmit=async event=>{event.preventDefault(); $('dialog-submit').disabled=true; try { await onSubmit(new FormData(event.currentTarget)); $('dialog').close(); }catch(error){$('dialog-status').textContent=error.message;}finally{$('dialog-submit').disabled=false;}};
  $('dialog').showModal();
}
function readValues(form) { return Object.fromEntries(form.entries()); }
function reasonDialog(title,action,extra={}) { openDialog(title,'<label>Reason<textarea name="reason" required maxlength="2000" rows="3"></textarea></label>',form=>command(action,matchPayload({...extra,reason:form.get('reason')})),title); }

function renderPanel() {
  if(!state.event)return;
  document.querySelectorAll('#event-tabs button').forEach(b=>b.setAttribute('aria-current',b.dataset.panel===state.panel?'page':'false'));
  document.querySelectorAll('section.panel').forEach(panel=>panel.hidden=panel.id!==`panel-${state.panel}`);
  ({overview:renderOverview,participants:renderPeople,rules:renderRules,live:renderLive,judge:renderJudge,vote:renderVote,results:renderResults,schedule:renderSchedule,help:renderHelp})[state.panel]?.();
}
function renderOverview() {
  const event=state.event,m=currentMatch();
  $('overview-content').innerHTML=`<div class="columns"><section><h2>Your event</h2><p>${esc(event.description || 'A three-speaker Modified Oxford–Oregon debate.')}</p><p>${esc(formatTime(event.scheduledAt))}</p><p>${esc(me()?.checkedIn?'You are checked in.':'Check in when you arrive.')}${me()?.admitted?'':' Admission is awaiting the host.'}</p><div class="actions">${host()?button('Edit event','edit-event')+button('Create invitation','invite')+button('Add team','team')+button('Add motion','motion')+button('Set up match','match','', 'primary'):''}${button('Retry last action','retry')}</div></section><section><h2>Ready to begin</h2>${m?`<p>${esc(m.title)} · ${esc(m.phase)}</p><ul>${(m.readiness?.issues || m.readiness?.reasons || []).map(issue=>`<li>${esc(typeof issue==='string'?issue:issue.message)}</li>`).join('')}</ul><p>${m.readiness?.ready?'All required readiness checks are confirmed.':'Complete roster, check-in, neutral officials, microphone checks, motion and captain acknowledgments.'}</p><div class="actions">${button('Record my microphone check','device-check')}${host()?button('Start match','start-match','', 'primary'):''}</div>`:'<p>Add two confirmed teams, a motion and at least one neutral judge, then set up the match.</p>'}</section></div><hr><h2>Organizer journey</h2><ol class="steps"><li>Create the event and invite participants.</li><li>Confirm teams, judges, sides, rules and readiness.</li><li>Release the motion and prepare privately.</li><li>Run every stage with the shared timer and assigned floor.</li><li>Complete adjudication, publish the provisional result and resolve corrections.</li><li>Finalize, export results and move to the next match.</li></ol>`;
}
function renderPeople() {
  $('participants-content').innerHTML=`<div class="section-heading"><h2>People</h2><div class="actions">${host()?button('Create invitation','invite')+button('Confirm team','team'):''}</div></div><div class="table-scroll"><table><thead><tr><th>Participant</th><th>Event roles</th><th>Arrival</th><th>Controls</th></tr></thead><tbody>${state.event.members.map(p=>`<tr><td>${esc(p.displayName)}</td><td>${esc(p.roles.join(', '))}</td><td>${p.removed?'Removed':!p.admitted?'Waiting for admission':p.checkedIn?'Checked in':'Invited'}</td><td>${host()?`${!p.admitted?button('Admit','admit',`data-person="${esc(p.id)}"`):''}${button('Roles','roles',`data-person="${esc(p.id)}"`)}`:''}${official()?button('Grant microphone','grant-floor',`data-person="${esc(p.id)}"`)+button('Presenter','presenter',`data-person="${esc(p.id)}"`):''}</td></tr>`).join('')}</tbody></table></div><hr><h2>Teams</h2><div class="columns">${state.event.teams.map(t=>`<section><h3>${esc(t.name)}</h3><p>${esc(t.school)}</p><ol>${t.speakerIds.map(p=>`<li>${esc(personName(p))}${p===t.captainId?' · Captain':''}</li>`).join('')}</ol>${host()?button('Edit team','team',`data-team="${esc(t.id)}"`):''}</section>`).join('')}</div>${host()?`<hr><h2>Invitations</h2><p class="muted">Privileged invitations require verified identity or explicit host approval. Invitations do not grant a judging ballot by themselves.</p>${state.event.invites.map(i=>`<p>${esc(i.role)} · ${i.revokedAt?'Revoked':`Expires ${esc(formatTime(i.expiresAt))}`} ${!i.revokedAt?button('Revoke','revoke-invite',`data-invite="${esc(i.id)}"`):''}</p>`).join('')}`:''}`;
}
function renderRules() {
  const m=currentMatch();
  $('rules-content').innerHTML=`<div class="section-heading"><h2>Rules &amp; motion</h2><div class="actions">${host()?button('Add motion','motion')+(m?button('Edit rules','edit-rules'):''):''}</div></div>${m?`<p>${esc(m.rules.preset)} · Version ${m.ruleVersion} · ${m.rulesLockedAt?'Locked for this match':'Open for confirmation'}</p><p>Constructive ${m.rules.constructiveMs/60000} minutes · Interpellation ${m.rules.interpellationMs/60000} minutes · Closing ${m.rules.rebuttalMs/60000} minutes</p><p>Official decision: ${esc(m.rules.judgingMode)}. Audience Choice is separate.</p><div class="actions">${button('Accept these rules and sides','acknowledge')}${host()?button('Release motion','release-motion')+button('Random side draw','draw-sides'):''}${button('Download rules PDF','export', 'data-kind="rules"')}</div>`:''}<hr><div>${state.event.motions.map(motion=>`<article><h3>${esc(motion.title)}</h3><p>${esc(motion.text)}</p><p class="muted">${motion.releasedAt?'Released to participants':'Private to the organizer until release'}</p></article>`).join('') || '<p>The motion has not been released to you.</p>'}</div><hr>${rulebook()}`;
}
function rulebook() {
  return `<h2>The 5/3/5 preset</h2><p>Each team has exactly three active speakers. The captain is one of those three; any assigned team speaker may deliver its closing.</p><p>Six alternating constructives take five minutes each. Each is followed by three minutes of questioning and answering with both assigned participants on the floor. After the optional five-minute private break, Negative closes, then Affirmative closes, five minutes each.</p><p>The timer starts only when its controller acts. At zero it counts overtime in red. Time alone does not mute, end a speech, penalize a team or decide a winner.</p><p>Default team score: average of the three individual subtotals (up to 85), plus one closing score (up to 15). Full scorecards use majority judge ballots unless aggregate scoring was selected before rules lock. Private drafts stay private.</p><p>Both captains accept the same rules. A neutral moderator handles objections, technical pauses and accommodations. No software decision replaces human judging. During questioning, new team messages to the active pair are blocked; previously received notes remain available.</p><p>This is the Due Diligence Modified Oxford–Oregon preset, not a universal national rulebook.</p><p class="muted">Source notes: <a href="https://www.recoletosdebaguio.edu.ph/2022/04/06/cares-holds-philosophical-debate-during-jornadas-de-filosofia-2022/" target="_blank" rel="noopener noreferrer">Casiciaco Recoletos Seminary</a>; <a href="https://ourhappyschool.com/debate/debate-tournament-framework-mechanics-guidelines-etc" target="_blank" rel="noopener noreferrer">Mañebog’s tournament framework</a>; <a href="https://catanduanes.deped.gov.ph/files/UM---Inter-Schools-Debate-for-the-Environment-and-Battle-of-Best-Partnership-Initiatives-and-Awarding-Ceremonies.pdf" target="_blank" rel="noopener noreferrer">DENR/DepEd event mechanics</a>. Timing, order and weights vary by event.</p>`;
}

function ensureTile(key,label,parent,identity,seat) {
  let tile=state.tiles.get(key);
  if(!tile){tile=document.createElement('article');tile.className='tile';tile.innerHTML='<span class="initials" aria-hidden="true"></span><div class="caption"><span></span><small>Camera off</small></div>';state.tiles.set(key,tile);}
  tile.dataset.identity=identity || ''; tile.dataset.seat=seat || '';
  tile.querySelector('.caption span').textContent=label;
  tile.querySelector('.initials').textContent=label.split(/\s+/).slice(0,2).map(x=>x[0]).join('');
  if(tile.parentElement!==parent)parent.append(tile);
  const existing=[...media.videos.values()].find(v=>v.identity===identity && v.source==='camera');
  if(existing && existing.element.parentElement!==tile)tile.prepend(existing.element);
  return tile;
}
function renderLive() {
  const m=currentMatch(); if(!m)return;
  const chosen=$('active-match').value;
  if($('active-match').options.length!==state.event.matches.length || !state.event.matches.some(x=>x.id===chosen))$('active-match').innerHTML=state.event.matches.map(x=>option(x.id,x.title,m.id)).join('');
  $('active-match').value=m.id;
  $('live-motion').textContent=state.event.motions.find(x=>x.id===m.motionId)?.text || 'Awaiting motion release';
  $('affirmative-name').textContent=state.event.teams.find(t=>t.id===m.teamIds?.affirmative)?.name || 'Affirmative';
  $('negative-name').textContent=state.event.teams.find(t=>t.id===m.teamIds?.negative)?.name || 'Negative';
  const stage=m.runOfShow?.[m.currentStageIndex]; const floorSeats=stage?.speakerSeats || [];
  for(const seat of SEATS){const user=m.seats[seat];const tile=ensureTile(seat,`${seat} · ${personName(user)}`,seat[0]==='A'?$('affirmative-tiles'):$('negative-tiles'),user?`dd-debate-${user}`:'',seat);tile.classList.toggle('on-floor',floorSeats.includes(seat));}
  const judgeKeys=new Set(m.judgeIds.map(x=>`judge-${x}`));
  for(const key of [...state.tiles.keys()])if(key.startsWith('judge-')&&!judgeKeys.has(key)){state.tiles.get(key).remove();state.tiles.delete(key);}
  for(const user of m.judgeIds)ensureTile(`judge-${user}`,`${personName(user)}${m.chiefId===user?' · Chief':''}`,$('judge-tiles'),`dd-debate-${user}`);
  const observers=state.event.members.filter(p=>p.admitted&&!p.removed&&!Object.values(m.seats).includes(p.id)&&!m.judgeIds.includes(p.id));
  const page=observers.slice(state.observerPage*6,state.observerPage*6+6);const pageKeys=new Set(page.map(p=>`observer-${p.id}`));
  for(const key of [...state.tiles.keys()])if(key.startsWith('observer-')&&!pageKeys.has(key)){state.tiles.get(key).remove();state.tiles.delete(key);}
  for(const user of page)ensureTile(`observer-${user.id}`,user.displayName,$('observer-tiles'),`dd-debate-${user.id}`);
  $('observers-prev').disabled=state.observerPage===0;$('observers-next').disabled=(state.observerPage+1)*6>=observers.length;
  $('stage-label').textContent=stage?.label || stage?.kind || m.phase;
  $('speaker-label').textContent=floorSeats.length?floorSeats.map(seat=>`${seat} · ${personName(m.seats[seat])}`).join(' ↔ '):m.phase==='setup'?'Complete readiness to begin':'Private preparation / deliberation';
  const next=m.runOfShow?.[m.currentStageIndex+1];$('next-stage').textContent=next?`Next: ${next.label || next.kind}`:'No next speaking stage';
  $('run-of-show').innerHTML=(m.runOfShow || []).map((s,i)=>`<li class="${i===m.currentStageIndex?'current':''}">${esc(s.label || `${s.id} ${s.kind}`)} · ${s.durationMs == null?'Untimed':`${s.durationMs/60000} min`}</li>`).join('');
  $('stage-controls').innerHTML=official()?`${button('Take timer control','claim-clock')}${m.timer?button('Start','timer','data-type="START"')+button(m.timer.state==='PAUSED'?'Resume':'Pause','timer',`data-type="${m.timer.state==='PAUSED'?'RESUME':'PAUSE'}"`)+button('Finish stage','timer','data-type="FINISH"')+button('Next stage','next-stage')+button('Return to stage','return-stage')+button('Technical pause','technical-pause'):''}`:'';
  $('private-space-controls').innerHTML=['main','affirmative','negative','judges'].map(space=>button(space==='main'?'Main room':space==='judges'?'Judge deliberation':`${sideName(space)} preparation`,'space',`data-space="${space}"`)).join('');
  if(state.lastStage!==stage?.id){state.lastStage=stage?.id;$('stage-announcement').textContent=`${$('stage-label').textContent}. ${$('speaker-label').textContent}`;}
  renderMessages();
  $('evidence-list').innerHTML=(m.evidence || []).map(e=>`<article><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p>${/^https?:\/\//i.test(e.url || e.sourceUrl || '')?`<a href="${esc(e.url || e.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}<small> · Version ${e.version || 1}</small></article>`).join('')||'<p class="muted">No shared evidence yet.</p>';
  updateClock();
}
function renderMessages(){const m=currentMatch();const channel=$('channel').value;const actual=channel==='team'?((m?.seats && Object.entries(m.seats).find(([,v])=>v===state.event.myId)?.[0] || 'A')[0]==='A'?'affirmative':'negative'):channel;
  $('messages').innerHTML=(m?.messages || []).filter(x=>x.channel===actual).map(message=>`<li><strong>${esc(personName(message.actorId || message.senderId))}</strong><time>${esc(formatTime(message.createdAt || message.at))}</time><p>${esc(message.text)}</p></li>`).join('');
  $('channel-policy').textContent=actual==='main'?'Visible to admitted participants.':actual==='judges'?'Assigned judges only.':'Private team channel. Active questioning participants cannot receive new team messages.';
}
function updateClock(){const m=currentMatch();if(!m?.timer){$('clock').textContent='Ready';return;}const display=timerDisplay(m.timer,serverNow());$('clock').textContent=display.text;$('clock').classList.toggle('overtime',display.overtime);$('clock-status').textContent=`${m.timer.state}${!state.sync||performance.now()-state.sync.local>15000?' · Stale — reconnecting':''}`;}

function renderJudge() {
  const m=currentMatch();if(!m){$('judge-content').innerHTML='<p>Create or select a match first.</p>';return;}
  if(!m.judgeIds.includes(state.event.myId)){$('judge-content').innerHTML=`<h2>Adjudication</h2><p>Only an assigned eligible judge can open their private scorecard.</p><p>${m.ballotCompletion.received} of ${m.ballotCompletion.required} final ballots received. Preferences remain private.</p>${official()?`<div class="actions">${button('Open final ballots','open-ballots')}${button('Close ballots','close-ballots')}${button('Panel change / recusal','panel-change')}</div>`:''}`;return;}
  if(state.judgeDirty)return;
  const draft=m.myDraft || {};const card=draft.card || draft.scorecard || {speakers:{},closing:{}};
  $('judge-content').innerHTML=`<div class="section-heading"><h2>My private scorecard</h2><p id="draft-status" role="status">${draft.savedAt?'Saved draft restored':'No saved draft yet'}</p></div><p>Scoring mode: ${esc(m.rules.judgingMode)}. Blanks are incomplete; an explicit zero is a score. Your private notes are not shared with the organizer or other judges.</p><form id="score-form">${m.rules.judgingMode==='simple'?`<label>Winner<select name="winner"><option value="">Choose a side</option>${['affirmative','negative'].map(s=>option(s,sideName(s),draft.winner)).join('')}</select></label>`:`<div class="table-scroll"><table><thead><tr><th>Speaker</th>${SPEAKER_CRITERIA.map(k=>`<th>${esc(m.rules.rubric.labels[k])}<br>0–${m.rules.rubric.weights[k]}</th>`).join('')}</tr></thead><tbody>${SEATS.map(seat=>`<tr><td>${seat}<br>${esc(personName(m.seats[seat]))}</td>${SPEAKER_CRITERIA.map(k=>`<td><input aria-label="${esc(`${seat} ${m.rules.rubric.labels[k]}`)}" name="${seat}.${k}" type="number" min="0" max="${m.rules.rubric.weights[k]}" step="0.01" value="${esc(card.speakers?.[seat]?.[k] ?? '')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="columns">${['affirmative','negative'].map(s=>field(`${sideName(s)} closing — ${personName(m.seats[m.closingSeats[s]])}`,`closing.${s}`,card.closing?.[s] ?? '', 'number',`min="0" max="${m.rules.rubric.weights.closing}" step="0.01"`)).join('')}</div><p id="score-preview" class="score-total"></p><label>Choice if exact scores are tied<select name="tieBreakChoice"><option value="">Only needed for an exact tied scorecard</option>${['affirmative','negative'].map(s=>option(s,sideName(s),draft.tieBreakChoice)).join('')}</select></label>`}<label>Reasoned decision / tie explanation<textarea name="reason" maxlength="4000" rows="3">${esc(draft.reason || '')}</textarea></label><label>Private notes<textarea name="notes" maxlength="12000" rows="5">${esc(draft.notes || '')}</textarea></label><div class="actions"><button type="submit" class="primary">Save private draft</button>${button('Review and submit final ballot','submit-ballot')}${button('My scorecard PDF','export','data-kind="scorecard"')}${button('Nominate Best Debater','nominate')}</div></form><p>Final ballots: ${esc(m.ballotState)} · ${m.ballotCompletion.received}/${m.ballotCompletion.required} received.</p>${official()?`<div class="actions">${button('Open final ballots','open-ballots')}${button('Close ballots','close-ballots')}${button('Panel change / recusal','panel-change')}</div>`:''}`;
  $('score-form').addEventListener('input',()=>{state.judgeDirty=true;$('draft-status').textContent='Unsaved changes';previewScore();});
  $('score-form').addEventListener('focusout',()=>{clearTimeout(state.draftTimer);state.draftTimer=setTimeout(()=>{if(state.judgeDirty&&!state.busy)saveDraft().catch(()=>{});},650);});
  $('score-form').onsubmit=async event=>{event.preventDefault();await guarded(saveDraft);};previewScore();
}
function scoreFormData(){const form=$('score-form');if(!form)return {};const values=new FormData(form);const card={speakers:Object.fromEntries(SEATS.map(seat=>[seat,Object.fromEntries(SPEAKER_CRITERIA.map(k=>[k,values.get(`${seat}.${k}`) || null]))])),closing:Object.fromEntries(['affirmative','negative'].map(s=>[s,values.get(`closing.${s}`)||null]))};return {card,winner:values.get('winner')||null,tieBreakChoice:values.get('tieBreakChoice')||null,reason:values.get('reason'),notes:values.get('notes')};}
function previewScore(){if(!$('score-preview'))return;try{const result=scoreScorecard(scoreFormData().card,currentMatch().rules);$('score-preview').textContent=`Affirmative ${result.affirmative?.display || result.teams?.affirmative?.display || 'Complete'} · Negative ${result.negative?.display || result.teams?.negative?.display || 'Complete'}`;}catch{$('score-preview').textContent='Complete every score to calculate team totals.';}}
async function saveDraft(){const payload=scoreFormData();const result=await command('save_draft',matchPayload(payload));state.judgeDirty=false;$('draft-status').textContent='Saved';return result;}

function renderVote(){const m=currentMatch(),p=m?.poll;if(!m){$('vote-content').innerHTML='<p>Select a match first.</p>';return;}$('vote-content').innerHTML=`<h2>Audience Choice</h2><p>Audience Choice is separate from official judging, awards and bracket progression. Every eligible observer has one current vote.</p>${!p?'<p>The host has not opened a poll.</p>':`<p>Poll: ${esc(p.state)}</p>${p.state==='Open'&&p.eligible?`<p>Your current choice: ${esc(p.myVote?sideName(p.myVote):'No vote')}</p><div class="actions">${button('Affirmative','vote','data-side="affirmative"')}${button('Negative','vote','data-side="negative"')}${button('Withdraw vote','withdraw-vote')}</div>`:p.state==='Open'?'<p>You are not in this poll’s eligible observer snapshot.</p>':''}${p.result?`<p>${esc(p.result.text || '')}</p><dl>${Object.entries(p.result).filter(([,v])=>typeof v==='number'||typeof v==='string').map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`:'<p>Totals remain private until the poll is closed and published.</p>'}`}${host()?`<hr><div class="actions">${button('Open poll','open-poll')}${button('Close poll','close-poll')}${button('Publish Audience Choice','publish-poll')}</div>`:''}`;}
function renderResults(){const m=currentMatch();if(!m){$('results-content').innerHTML='<p>Select a match first.</p>';return;}const result=m.resultVersions.filter(r=>r.state!=='SUPERSEDED').at(-1);
  $('results-content').innerHTML=`<h2>Official result</h2>${result?`<p>${esc(result.state)} · Result version ${result.version || result.revision}</p><div class="result-winner">${esc(result.winner?sideName(result.winner):result.tabulation?.winner?sideName(result.tabulation.winner):'Unresolved')}</div><p>Decision method: ${esc(m.rules.judgingMode)}</p><div id="result-summary"></div><h3>Awards</h3><div id="awards-summary"></div><p>Audience Choice is reported separately on the Vote tab.</p><div class="actions">${button('Download result PDF','export','data-kind="result"')}${button('Download safe CSV','export','data-kind="csv"')}${button('Report a procedural error','protest')}${host()?button('Send results','send-results')+button('Issue certificate','export','data-kind="certificate"'):''}</div>`:'<p>Results have not been published. Final ballots must be complete before tabulation.</p>'}${official()?`<hr><div class="actions">${button('Publish provisional result','publish-result')}${button('Finalize result','finalize-result')}${button('Correct result','correct-result')}${button('Reconsider tied result','reconsider')}</div>`:''}<hr><h3>Procedural reports</h3>${m.protests.map(p=>`<article><p>${esc(p.reason)} · ${esc(p.status || p.state)}</p>${official()?button('Resolve report','resolve-protest',`data-protest="${esc(p.id)}"`):''}</article>`).join('')||'<p>No visible procedural reports.</p>'}<h3>Exports and delivery</h3>${state.event.outbox.map(j=>`<p>${esc(j.type)} · ${esc(j.status)}${j.error?` · ${esc(j.error)}`:''} ${j.downloadId?button('Download','download',`data-download="${esc(j.downloadId)}"`):''}${['failed','queued'].includes(j.status)?button('Retry','retry-job',`data-job="${esc(j.id)}"`)+button('Cancel','cancel-job',`data-job="${esc(j.id)}"`):''}</p>`).join('')||'<p>No export or delivery jobs yet.</p>'}`;
  if(result){renderRecord($('result-summary'),result.tabulation || result.summary || result.result || {});renderRecord($('awards-summary'),result.awards || {});}}
function renderRecord(parent,data){const dl=document.createElement('dl');for(const [key,value]of Object.entries(data)){if(['ballots','scorecards','privateNotes'].includes(key))continue;const dt=document.createElement('dt');dt.textContent=key.replace(/([A-Z])/g,' $1');const dd=document.createElement('dd');if(value&&typeof value==='object'){if(Array.isArray(value))dd.textContent=value.map(x=>typeof x==='object'?x.name||x.seat||x.winner||'See event details':String(x)).join(', ');else renderRecord(dd,value);}else dd.textContent=String(value??'—');dl.append(dt,dd);}parent.append(dl);}
function renderSchedule(){$('schedule-content').innerHTML=`<div class="section-heading"><h2>Matches &amp; standings</h2><div class="actions">${host()?button('Set up match','match')+button('Generate fixtures','fixtures')+button('Event report PDF','export','data-kind="event"'):''}</div></div><p>Sequential matches are the default. Provisional or unresolved results cannot advance a dependent official match.</p>${state.event.matches.map(m=>`<article><h3>${esc(m.title)}</h3><p>${esc(m.phase)} · ${esc(m.judgingMode || m.rules.judgingMode)}</p>${button('Open match','select-match',`data-match="${esc(m.id)}"`)}${host()?button('Advance to match','advance-match',`data-match="${esc(m.id)}"`):''}</article>`).join('<hr>')}<hr><div id="fixtures-summary"></div><div id="standings-summary"></div>`;renderRecord($('fixtures-summary'),{fixtures:state.event.fixtures});if(state.event.standings)renderRecord($('standings-summary'),state.event.standings);}
function renderHelp(){const m=currentMatch();$('help-content').innerHTML=`<div class="columns"><section><h2>Host &amp; moderator</h2><p>Confirm seats and neutral officials. Release the motion to both teams together. Explicitly start each stage; Next loads a ready clock. During questioning, both assigned speakers receive microphone permission. A grant never activates another person’s device.</p><p>Moderator script: “The motion is before the house. We now invite the assigned speaker. The questioning period includes both questions and answers. At the end, the panel will deliberate under the accepted rules.”</p><h2>Speaker</h2><p>Check in, verify your microphone, and accept your team’s rules as captain. Choose Mic when your floor permission is ready. Use Technical help if media fails; disconnection does not automatically forfeit the match.</p></section><section><h2>Judge</h2><p>Save private notes during speeches. Explicitly enter every score, review, and submit when final ballots open. Missing scores are not zero. A tied scorecard needs a reasoned choice; a tied panel remains unresolved under the declared process.</p><h2>Observer</h2><p>Camera begins off. Request the floor before speaking. Audience voting needs checked-in observer eligibility at poll opening; it never decides the official winner.</p></section></div><hr><h2>Connection and device help</h2><p>Enter room before turning on devices. If sound is blocked, use Enable sound. Screen audio depends on the browser and selected capture source; screen video alone does not prove shared audio. If an effect fails, camera stays safe and audio can continue. Select None explicitly only if you consent to showing your background.</p><div class="actions">${button('Request help or ruling','request-help')}${button('Retry last unconfirmed action','retry')}${official()?button('End match / exceptional conclusion','conclude')+button('Substitute registered reserve','substitute'):''}</div><hr><h2>Help queue</h2>${(m?.incidents || []).map(i=>`<article><p>${esc(i.kind || i.type)} · ${esc(i.reason)} · ${esc(i.status || i.state)}</p>${official()?button('Acknowledge / resolve','resolve-incident',`data-incident="${esc(i.id)}"`):''}</article>`).join('')||'<p>No visible requests.</p>'}<hr><h2>Written records</h2><p>Preview retention defaults: chat and unsubmitted notes 30 days after event end; evidence 90 days; official scorecards, results, rules and audit 365 days. An approved dispute hold can suspend deletion. Recording, transcription and livestreaming are not enabled.</p>`;}

async function guarded(fn){try{return await fn();}catch(error){status(error.message,true);}}
const media=new DebateMedia({audioRoot:$('audio-elements'),presentation:$('presentation'),onIssue:message=>status(message,true),onState:value=>{
  $('media-status').textContent=value.joined?'Connected. Your devices follow your choices and the current floor.':value.state==='disconnected'?'You are outside live media. The competition record remains saved.':`Room connection: ${value.state}`;
  for(const [key,label,on]of [['mic','Mic',value.microphone],['camera','Camera',value.camera],['share','Share',value.share]]){$(key).setAttribute('aria-pressed',String(on));$(key).textContent=`${label}${key==='share'?'':on?' on':' off'}`;$(key).disabled=!value.joined;}
},onVideo:(identity,video,label)=>{const tile=[...state.tiles.values()].find(t=>t.dataset.identity===identity);if(!tile)return;if(video&&video.parentElement!==tile)tile.prepend(video);tile.querySelector('.caption small').textContent=label;}});

