  'export':b=>command('create_export',matchPayload({kind:b.dataset.kind})), 'retry-job':b=>command('retry_job',{jobId:b.dataset.job}), 'cancel-job':b=>command('cancel_job',{jobId:b.dataset.job}),
  'download':async b=>{const response=await fetch(`${apiBase}/debate-room/download?eventId=${encodeURIComponent(state.event.id)}&downloadId=${encodeURIComponent(b.dataset.download)}`,{headers:{Authorization:`Bearer ${state.session.access_token}`},cache:'no-store'});if(!response.ok)throw new Error('The download is unavailable or your permission changed.');const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=response.headers.get('X-Debate-Filename')||'duediligence-debate-result.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),20000);},
  'invite':()=>openDialog('Create invitation',`<label>Role<select name="role">${['observer','debater','judge','moderator','timekeeper','cohost','coach','reserve'].map(r=>option(r,r)).join('')}</select></label>${field('Intended verified email (required for privileged automatic assignment)','email','','email')}<label class="inline"><input name="requiresApproval" type="checkbox" checked>Host approves privileged role after sign-in</label>`,async form=>{const result=await command('create_invite',{role:form.get('role'),email:form.get('email'),requiresApproval:form.get('requiresApproval')==='on'});setTimeout(()=>openDialog('Invitation ready',`<p>Share this invitation only with the intended participants. It can be revoked from People.</p><textarea readonly rows="4">${esc(`${location.origin}${location.pathname}#event=${state.event.id}&invite=${result.secret || result.code}`)}</textarea><p>Code: ${esc(result.code || result.secret)}</p>`,async()=>{},'Done'),0);},'Create invitation'),
  'team':b=>{const t=state.event.teams.find(t=>t.id===b.dataset.team);openDialog('Confirm team',`${field('Team name','name',t?.name || '','text','required maxlength="120"')}${field('School / affiliation (optional)','school',t?.school || '')}${[1,2,3].map((n,i)=>selectPerson(`Speaker ${n}`,`speaker${n}`,t?.speakerIds[i])).join('')}${selectPerson('Captain (one of these speakers)','captainId',t?.captainId)}`,form=>command('confirm_roster',{teamId:t?.id,name:form.get('name'),school:form.get('school'),speakerIds:[1,2,3].map(n=>form.get(`speaker${n}`)),captainId:form.get('captainId')}),'Confirm roster');},
  'motion':()=>openDialog('Add private motion',`${field('Motion title','title','','text','required maxlength="160"')}<label>Motion<textarea name="text" required maxlength="8000" rows="5"></textarea></label>`,form=>command('add_motion',readValues(form))),
  'edit-event':()=>eventDialog(state.event),
  'roles':b=>openDialog('Assign event role',`<p>${esc(personName(b.dataset.person))}</p><label>Role<select name="role">${['observer','debater','judge','moderator','timekeeper','cohost','coach','reserve'].map(r=>option(r,r)).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>command('assign_role',{memberId:b.dataset.person,...readValues(form)})),
  'device-check':()=>openDialog('Confirm microphone readiness',`<p>Use a real microphone test with another participant. A checked box is your report, not a measured audio test.</p><label class="inline"><input type="checkbox" name="microphoneReady">I confirmed my microphone is audible</label><label>Accommodation / issue<textarea name="accommodation" maxlength="2000"></textarea></label>`,form=>command('record_device_check',matchPayload({microphoneReady:form.get('microphoneReady')==='on',accommodation:form.get('accommodation')}))),
  'match':()=>matchDialog(), 'edit-rules':()=>rulesDialog(),
