  'conclude':()=>openDialog('Conclude match',`<label>Conclusion<select name="kind"><option value="normal">Complete speaking phase</option><option value="forfeit">Single forfeit</option><option value="double_forfeit">Double forfeit</option><option value="cancelled">Cancel match</option><option value="withdrawal">Withdrawal</option></select></label><label>Forfeiting side (if applicable)<select name="side"><option value="">None</option>${['affirmative','negative'].map(s=>option(s,sideName(s))).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label>`,form=>command('conclude_match',matchPayload(readValues(form))),'Confirm conclusion'),
